import { useState } from "react";
import { View, Text, Pressable } from "react-native";

// Ngăn xếp điều hướng tối giản: mảng các màn hình {name, params}
export default function App() {
  const [stack, setStack] = useState([{ name: "Home" }]);
  const top = stack[stack.length - 1];
  const push = (name, params) => setStack([...stack, { name, params }]);
  const pop = () => stack.length > 1 && setStack(stack.slice(0, -1));

  return (
    <View>
      <Text testID="screen">{top.name}{top.params ? ":" + top.params.id : ""}</Text>
      <Text testID="depth">{stack.length}</Text>
      {top.name === "Home" && (
        <Pressable testID="open" onPress={() => push("Detail", { id: 7 })}><Text>Mở chi tiết</Text></Pressable>
      )}
      {stack.length > 1 && <Pressable testID="back" onPress={pop}><Text>Quay lại</Text></Pressable>}
    </View>
  );
}

