import { useState } from "react";
import { View, Text, Pressable } from "react-native";

const PEOPLE = ["An", "Bình", "Chi"];

export default function App() {
  const [selected, setSelected] = useState(null);
  if (selected) {
    return <View><Text testID="detail">{selected}</Text><Pressable testID="x" onPress={() => setSelected(null)}><Text>Về</Text></Pressable></View>;
  }
  return (
    <View>
      {PEOPLE.map((name, i) => (
        <Pressable key={name} testID={"p" + (i + 1)} onPress={() => setSelected(name)}><Text>{name}</Text></Pressable>
      ))}
    </View>
  );
}
